"""Manual simulator control via stdin; steady-time watchdog and Nav2 interlock."""
import json
import math
from pathlib import Path
import sys
import threading
import time
import rclpy
from geometry_msgs.msg import Twist
from lifecycle_msgs.srv import GetState
from rclpy.node import Node


def decode(line):
    data = json.loads(line)
    v, w = float(data['v']), float(data['w'])
    if not math.isfinite(v) or not math.isfinite(w):
        raise ValueError('Non-finite control input')
    if data.get('held') is not True:
        return 0., 0.
    return max(-.12, min(.15, v)), max(-.5, min(.5, w))


class Bridge(Node):
    def __init__(self):
        super().__init__('vacuum_manual_controller')
        self.pub = self.create_publisher(Twist, '/cmd_vel_smoothed', 1)
        self.lock = threading.Lock()
        self.latest = (0., 0.)
        self.received = 0.
        self.closed = False
        self.states = {name: (0, 0.) for name in ('controller_server', 'bt_navigator', 'collision_monitor')}
        self.clients = {name: self.create_client(GetState, f'/{name}/get_state') for name in self.states}
        self.pending = {}
        self.create_timer(.05, self.tick)
        self.create_timer(.25, self.check_states)
        threading.Thread(target=self.read_input, daemon=True).start()

    def read_input(self):
        try:
            for line in sys.stdin:
                try:
                    command = decode(line)
                except (ValueError, KeyError, TypeError):
                    command = (0., 0.)
                with self.lock:
                    self.latest = command
                    self.received = time.monotonic()
        finally:
            with self.lock:
                self.latest = (0., 0.)
                self.closed = True

    def check_states(self):
        for name, client in self.clients.items():
            previous = self.pending.get(name)
            if previous and not previous.done():
                continue
            if not client.service_is_ready():
                continue
            future = client.call_async(GetState.Request())
            self.pending[name] = future
            future.add_done_callback(lambda result, name=name: self.record(name, result))

    def record(self, name, future):
        try:
            self.states[name] = (future.result().current_state.id, time.monotonic())
        except Exception:
            self.states[name] = (0, 0.)

    def tick(self):
        now = time.monotonic()
        safe = all(state == (3 if name == 'collision_monitor' else 2) and now - stamp < 1.
                   for name, (state, stamp) in self.states.items())
        with self.lock:
            v, w = self.latest if safe and now - self.received < .3 else (0., 0.)
            closed = self.closed
        message = Twist()
        message.linear.x, message.angular.z = v, w
        self.pub.publish(message)
        if closed:
            raise KeyboardInterrupt


def main():
    # The launcher lock, separate from the simulator lock, serializes manual sources.
    import fcntl
    path = Path('/home/robot/vacuum_ws/.lab/manual-input.lock')
    with path.open('a') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        rclpy.init()
        node = Bridge()
        try:
            rclpy.spin(node)
        except KeyboardInterrupt:
            pass
        finally:
            node.pub.publish(Twist())
            node.destroy_node()
            if rclpy.ok():
                rclpy.shutdown()


if __name__ == '__main__':
    main()

